using namespace cinema;

// A minimal valid perimeter gives one canonical pixel to each independent camera.
static wled::CinemaConfig makeConfig(uint8_t smoothness = 0) {
  wled::CinemaConfig config;
  config.enabled = true;
  config.generation = 7;
  config.topLeds = 2;
  config.color.colorBoost = config.color.darkColorBoost = config.color.blackThreshold = 0;
  config.color.smoothness = smoothness;
  return config;
}

// Injects a decoded RGB frame at the same consumer used after SPI packet validation.
static bool sendFrame(wled::CinemaController& controller, uint32_t sequence, uint32_t frameId, uint8_t red = 255,
                      protocol::NodeRole side = protocol::NodeRole::CameraLeft, uint32_t bootId = 42, uint32_t generation = 7) {
  uint8_t colors[] = {red, 0, 0};
  uint8_t payload[protocol::FRAME_RGB_HEADER_SIZE + sizeof(colors)];
  protocol::FrameRgbHeader header;
  header.configGeneration = generation;
  header.frameId = frameId;
  header.slotCount = 1;
  size_t size = 0;
  assert(protocol::encodeFrameRgbPayload(header, colors, sizeof(colors), payload, sizeof(payload), &size) == protocol::PacketStatus::Ok);
  protocol::PacketView packet;
  packet.header.source = side;
  packet.header.target = protocol::NodeRole::Controller;
  packet.header.type = protocol::MessageType::FrameRgb;
  packet.header.sequence = sequence;
  packet.header.bootId = bootId;
  packet.payload = payload;
  packet.payloadSize = static_cast<uint16_t>(size);
  return controller.processPacket(packet, side, millis());
}

// Applies real SPI setup while keeping every test's pin and DMA ownership balanced.
static void start(wled::CinemaController& controller, uint8_t smoothness = 0) {
  cinemaTest::nowMillis = 10000;
  assert(controller.applyConfig(makeConfig(smoothness)));
  controller.begin();
  controller.service(millis());
  assert(controller.transportReady());
}

// Freshness uses unsigned uptime, including a frame received exactly at the millis rollover.
static void testUptimeAndTimeout() {
  wled::CinemaController controller;
  start(controller);
  assert(sendFrame(controller, 10, 10));
  Segment segment;
  cinemaTest::nowMillis = 10020;
  assert(controller.render(segment)); // No effect clock can enter this API.
  assert(segment.pixels[0] == 0xFF0000);
  cinemaTest::nowMillis = 10150;
  controller.render(segment);
  assert(segment.pixels[0] == 0xFF0000);
  cinemaTest::nowMillis++;
  controller.render(segment);
  assert(segment.pixels[0] == 0);
  // Unsigned uptime arithmetic must also survive the 32-bit millis rollover.
  cinemaTest::nowMillis = UINT32_MAX - 20;
  assert(sendFrame(controller, 11, 11));
  cinemaTest::nowMillis = 10;
  controller.render(segment);
  assert(segment.pixels[0] == 0xFF0000);
  cinemaTest::nowMillis = 0;
  assert(sendFrame(controller, 12, 12));
  cinemaTest::nowMillis = 10;
  controller.render(segment);
  assert(segment.pixels[0] == 0xFF0000);
  controller._spiMaster.end();
}

// Losing one camera clears only its filter history; live black samples must also converge.
static void testSmoothingAndCameraIsolation() {
  for (uint8_t smoothness : {uint8_t(192), uint8_t(255)}) {
    wled::CinemaController controller;
    start(controller, smoothness);
    assert(sendFrame(controller, 10, 10));
    assert(sendFrame(controller, 10, 10, 255, protocol::NodeRole::CameraRight, 43));
    Segment segment;
    for (int i = 0; i < 2000; i++) controller.render(segment);
    assert(segment.pixels[0] > 0 && segment.pixels[1] > 0);
    cinemaTest::nowMillis += 100;
    assert(sendFrame(controller, 11, 11, 255, protocol::NodeRole::CameraRight, 43));
    cinemaTest::nowMillis += 51;
    controller.render(segment);
    assert(segment.pixels[0] == 0 && segment.pixels[1] > 0);
    assert(controller._smoothedPixels[0] == 0);
    // A healthy camera reporting black must converge too, without relying on a timeout.
    assert(sendFrame(controller, 12, 12, 0, protocol::NodeRole::CameraRight, 43));
    for (int i = 0; i < 10000; i++) controller.render(segment);
    assert(segment.pixels[1] == 0);
    controller._spiMaster.end();
  }
}

// A new boot session clears only that camera's history and restarts its sequence/frame IDs.
static void testCameraRebootAndOrdering() {
  wled::CinemaController controller;
  start(controller, 192);
  assert(sendFrame(controller, 100, 100));
  assert(sendFrame(controller, 100, 100, 255, protocol::NodeRole::CameraRight, 43));
  Segment segment;
  for (int i = 0; i < 1000; i++) controller.render(segment);
  const uint16_t rightHistory = controller._smoothedPixels[3];
  assert(sendFrame(controller, 1, 1, 255, protocol::NodeRole::CameraLeft, 99));
  assert(controller._smoothedPixels[0] == 0 && controller._smoothedPixels[3] == rightHistory);
  assert(!sendFrame(controller, 1, 1, 255, protocol::NodeRole::CameraLeft, 99));
  assert(!sendFrame(controller, 2, 0, 255, protocol::NodeRole::CameraLeft, 99));
  assert(!sendFrame(controller, 3, 2, 255, protocol::NodeRole::CameraLeft, 99, 8));
  assert(sendFrame(controller, 4, 2, 255, protocol::NodeRole::CameraLeft, 99));
  controller._spiMaster.end();
}

// Interleave a real save thread with SPI setup and verify the next loop consumes its snapshot.
static void testConfigDuringSpiInitialization() {
  wled::CinemaController controller;
  auto initial = makeConfig();
  auto next = initial;
  next.generation = 8;
  next.topLeds = 4;
  assert(controller.applyConfig(initial));
  controller.begin();
  cinemaTest::onBusInitialize = [&] {
    // Match a save on the HTTP task while the WLED loop initializes its old snapshot.
    std::thread save([&] { assert(controller.applyConfig(next)); });
    save.join();
  };
  controller.service(millis());
  cinemaTest::onBusInitialize = {};
  assert(controller._config.generation == 7);
  assert(controller.config().generation == 8);
  controller.service(millis());
  assert(controller._config.generation == 8 && controller._config.topLeds == 4);
  controller._spiMaster.end();
}

// Validate return-wire selection, slot-error isolation and all-or-nothing pin/DMA ownership.
static void testSpiReturnsAndFailureCleanup() {
  wled::CinemaSpiMaster master;
  const auto config = makeConfig().spi;
  auto invalid = config;
  invalid.rightMisoPin = invalid.misoPin;
  assert(!master.begin(invalid, makeConfig().streamConfig()));
  assert(master.status() == wled::CinemaSpiStatus::InvalidConfig);
  invalid.rightMisoPin = -1;
  assert(invalid.isStructurallyValid() && !invalid.isComplete());
  assert(!master.begin(invalid, makeConfig().streamConfig()));
  cinemaTest::conflictPin = config.rightMisoPin;
  assert(!master.begin(config, makeConfig().streamConfig()));
  assert(master.status() == wled::CinemaSpiStatus::PinConflict);
  cinemaTest::conflictPin = -1;
  cinemaTest::failAllocation = cinemaTest::allocationCalls + 2;
  assert(!master.begin(config, makeConfig().streamConfig()));
  assert(master.status() == wled::CinemaSpiStatus::NoMemory);
  assert(cinemaTest::liveAllocations == 0);
  assert(std::none_of(cinemaTest::ownedPins.begin(), cinemaTest::ownedPins.end(), [](bool owned) { return owned; }));
  cinemaTest::failAllocation = -1;
  assert(master.begin(config, makeConfig().streamConfig()));
  assert(cinemaTest::matrixFlags & SPICOMMON_BUSFLAG_GPIO_PINS);
  cinemaTest::returnPins.clear();
  protocol::PacketView packet;
  protocol::NodeRole expected;
  assert(master.poll(&packet, &expected, 10000));
  assert(packet.header.source == protocol::NodeRole::CameraLeft && expected == packet.header.source);
  assert(master.poll(&packet, &expected, 10016));
  assert(packet.header.source == protocol::NodeRole::CameraRight && expected == packet.header.source);
  assert((cinemaTest::returnPins == std::vector<int>{19, 21}));
  cinemaTest::corruptSlot = true;
  assert(!master.poll(&packet, &expected, 10032));
  assert(master.slotErrors() == 1);
  assert(master.poll(&packet, &expected, 10048)); // One bad camera slot cannot block the other return.
  assert(expected == protocol::NodeRole::CameraRight);
  master.end();
}

int main() {
  testUptimeAndTimeout();
  testSmoothingAndCameraIsolation();
  testCameraRebootAndOrdering();
  testConfigDuringSpiInitialization();
  testSpiReturnsAndFailureCleanup();
  assert(cinemaTest::liveAllocations == 0 && !cinemaTest::busActive);
  assert(std::none_of(cinemaTest::ownedPins.begin(), cinemaTest::ownedPins.end(), [](bool owned) { return owned; }));
  std::cout << "Cinema regression checks passed: uptime, timeout, smoothing, config handoff, MISO isolation, resource cleanup.\n";
}
